    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    let mut attempts = 0;
    let mut retry_index = 0;

    loop {
        attempts += 1;
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if error.is_transient() && attempts < config.max_attempts => {
                sleeper.sleep_ms(config.delay_for_retry(retry_index));
                retry_index += 1;
            }
            Err(error) => return Err(error),
        }
    }
}

