#[cfg(test)]
mod tests {
    use super::*;

    fn config(max_attempts: u32, base_delay_ms: u64, max_delay_ms: u64) -> RetryConfig {
        RetryConfig {
            max_attempts,
            base_delay_ms,
            max_delay_ms,
        }
    }

    #[test]
    fn retries_transient_errors_with_bounded_exponential_delays() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;

        let result = run_job(&config(4, 10, 25), &mut sleeper, || {
            calls += 1;
            if calls < 4 {
                Err(RetryError::Transient("temporary".into()))
            } else {
                Ok(())
            }
        });

        assert_eq!(result, Ok(()));
        assert_eq!(calls, 4);
        assert_eq!(sleeper.sleeps, vec![10, 20, 25]);
    }

    #[test]
    fn permanent_errors_return_without_retrying() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;

        let result = run_job(&config(5, 10, 100), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Permanent("invalid input".into()))
        });

        assert_eq!(result, Err(RetryError::Permanent("invalid input".into())));
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn max_attempts_includes_the_initial_call() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;

        let result = run_job(&config(3, 1, 100), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Transient("still unavailable".into()))
        });

        assert_eq!(result, Err(RetryError::Transient("still unavailable".into())));
        assert_eq!(calls, 3);
        assert_eq!(sleeper.sleeps, vec![1, 2]);
    }
}

